private GUPPricingAttributeGroup getAndValidateAttributeGroup(Name _name)
{
    GUPPricingAttributeGroup attributeGroup;
    select firstonly attributeGroup
        where attributeGroup.Name == _name 
        && attributeGroup.SourceLevel == GUPPricingAttributeSourceLevel::Header 
        && attributeGroup.GroupType == GUPPricingAttributeGroupType::General;

    if (!attributeGroup)
    {
        throw error(strfmt("@GlobalUnifiedPricing:GUPDataEntityInvalidRelationError", tablePName(GUPPricingAttributeGroup), _name));
    }

    return attributeGroup;
}

private boolean createOrUpdatePricingRuleCondition(RefRecId _ruleId, GUPRefRecId _conditionAttribute, AttributeValueText _value, str _fieldName)
{
    GUPPricingRuleCondition condition = GUPPricingRuleCondition::find(_ruleId, _conditionAttribute, true);
    if (condition)
    {
        condition.ConditionValue = _value;
        if (!condition.validateWrite())
        {
            throw error(strfmt("@GlobalUnifiedPricing:GUPDataEntityInvalidFieldValue", _value, _fieldName));
        }
        condition.update();
    }
    else
    {
        condition.RuleId = _ruleId;
        condition.ConditionAttribute = _conditionAttribute;
        condition.ConditionValue = _value;
        if (!condition.validateWrite())
        {
            throw error(strfmt("@GlobalUnifiedPricing:GUPDataEntityInvalidFieldValue", _value, _fieldName));
        }
        condition.insert();
    }
    return true;
}

private void createOrUpdateRule(RetailPeriodicDiscount _discount, GUPGroupAll _type, GUPPricingAttributeGroupName _groupName)
{
    GUPPricingRule rule = GUPPricingRule::find(_discount.HeaderPricingRule, true);
    switch (_type)
    {
        case GUPGroupAll::All :
            if (!rule)
            {
                rule = GUPPricingRule::newPricingRule("", GUPPricingRuleExclusionType::Customer);
                _discount.HeaderPricingRule = rule.RecId;
            }
            if (rule.PriceAttributeGroupName)
            {
                rule.PriceAttributeGroupName = "";
                rule.update();
            }
            break;
        case GUPGroupAll::Group :
            ttsbegin;
            GUPPricingAttributeGroup attributeGroup = this.getAndValidateAttributeGroup(_groupName);
            if (!rule)
            {
                rule = GUPPricingRule::newPricingRule(attributeGroup.Name, GUPPricingRuleExclusionType::Customer);
                _discount.HeaderPricingRule = rule.RecId;
            }
            if (rule.PriceAttributeGroupName != attributeGroup.Name)
            {
                rule.PriceAttributeGroupName = attributeGroup.Name;
                rule.update();
            }
            int num = 1;
            str baseFieldName = "Header";
            GUPPricingAttributeLink attributeLink;
            while select attributeLink
                    order by attributeLink.Priority asc
                    where attributeLink.PriceAttributeGroupName == attributeGroup.Name
            {
                this.createOrUpdatePricingRuleCondition(rule.RecId, attributeLink.RecId, this.getFieldValue(baseFieldName + int2Str(num)), baseFieldName + int2Str(num));
                num ++;
            }
            ttscommit;
    }
}

private void updatePriceComponentCode(GUPPriceComponentCodeName _name, GUPGroupAll _type, Name _groupName)
{
    GUPPriceComponentCode componentCode;
    select firstonly componentCode 
        where componentCode.PriceComponent == GUPPriceComponent::PriceMarginComponentAdjustment && componentCode.Name == _name;
    if (!componentCode)
    {
        throw error(strfmt("@GlobalUnifiedPricing:GUPDataEntityInvalidRelationError", tablePName(GUPPriceComponentCode), _name));
    }

    if (_type == GUPGroupAll::All && !componentCode.HeaderPriceAttributeGroupAllEnabled)
    {
        throw error(strfmt("@GlobalUnifiedPricing:GUPPriceComponentCode_TypeAllNotEnabledError", _name));
    }

    if (_type == GUPGroupAll::Group)
    {
        GUPPriceComponentCodePriceAttributeGroupCombination groupCombination;
        select firstonly groupCombination 
            where groupCombination.PriceComponentCodeName == _name 
            && groupCombination.HeaderPriceAttributeGroupName == _groupName;
        if (!groupCombination)
        {
            throw error(strfmt("@GlobalUnifiedPricing:GUPDataEntityInvalidRelationError", "Attribute group combination", _groupName));
        }
    }
}

public void postLoad()
{
    super();
    if (this.PriceAttributeGroupType == GUPGroupAll::Group && this.HeaderPricingRule)
    {
        GUPPricingRule rule;
        select firstonly crosscompany rule where rule.RecId == this.HeaderPricingRule;

        if (rule.PriceAttributeGroupName)
        {
            int num = 1;
            str baseFieldName = "Header";
            GUPPricingRuleCondition ruleCondition;
            GUPPricingAttributeLink attributeLink;
            while select crosscompany ruleCondition
            where ruleCondition.RuleId == this.HeaderPricingRule
            join attributeLink
            order by attributeLink.Priority asc
            where ruleCondition.ConditionAttribute == attributeLink.RecId
            {
                this.setFieldValue(baseFieldName + int2Str(num), ruleCondition.ConditionValue);
                num++;
            }
        }
    }
}

public void initializeEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    switch (_dataSourceCtx.name())
    {
        case dataEntityDataSourceStr(GUPMarginComponentPriceAdjustmentEntity, RetailPeriodicDiscount) :
            RetailPeriodicDiscount discount = _dataSourceCtx.getBuffer();
            _dataSourceCtx.setBuffer(discount as RetailDiscountOffer);
            break;
        case dataEntityDataSourceStr(GUPMarginComponentPriceAdjustmentEntity, GUPPricingRule) :
            _dataSourceCtx.setDataSaved(true);
            _dataSourceCtx.setDatabaseOperation(DataEntityDatabaseOperation::None);
            break;
    }
    super(_entityCtx, _dataSourceCtx);
}

public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean ret = true;
    switch (_dataSourceCtx.name())
    {
        case dataEntityDataSourceStr(GUPMarginComponentPriceAdjustmentEntity, RetailPeriodicDiscount) :
            RetailPeriodicDiscount discount = _dataSourceCtx.getBuffer();
            discount.Status = false;
            discount.IsGupDiscount = NoYes::Yes;
            discount.PriceComponentType = GUPPriceComponent::PriceMarginComponentAdjustment;
            discount.PeriodicDiscountType = RetailDiscountOfferTypeBase::Promotion;
            this.updatePriceComponentCode(this.PriceComponentCodeName, this.PriceAttributeGroupType, this.PriceAttributeGroupName);
            this.createOrUpdateRule(discount, this.PriceAttributeGroupType, this.PriceAttributeGroupName);
            break;
    }
    return ret && super(_entityCtx, _dataSourceCtx);
}

public boolean updateEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean ret = true;
    switch (_dataSourceCtx.name())
    {
        case dataEntityDataSourceStr(GUPMarginComponentPriceAdjustmentEntity, RetailPeriodicDiscount) :
            RetailPeriodicDiscount discount = _dataSourceCtx.getBuffer();
            if (this.orig().Status == RetailDisabledEnabled::Enabled && this.Status == RetailDisabledEnabled::Enabled)
            {
                throw error(strFmt("@RetailDiscount:NotAllowEditEnabledDiscount"));
            }
            discount.IsGupDiscount = NoYes::Yes;
            discount.PriceComponentType = GUPPriceComponent::PriceMarginComponentAdjustment;
            discount.PeriodicDiscountType = RetailDiscountOfferTypeBase::Promotion;
            this.updatePriceComponentCode(this.PriceComponentCodeName, this.PriceAttributeGroupType, this.PriceAttributeGroupName);
            this.createOrUpdateRule(discount, this.PriceAttributeGroupType, this.PriceAttributeGroupName);
            break;
    }
    return ret && super(_entityCtx, _dataSourceCtx);
}
